import { z } from 'zod';
import type {
  AgentDetail,
  AgentView,
  BrainConfig,
  LifeStage,
  LlmCallView,
  ProviderId,
  Sex,
} from './agent.ts';
import type { WorldEvent } from './events.ts';
import type { WireMap } from './map.ts';
import { BrainConfigSchema } from './settings.ts';
import type { CalendarView } from './time.ts';
import type { WorldMeta, WorldSettings } from './world.ts';

/** World ids are generated by the server; the pattern also guards file paths. */
export const WORLD_ID_PATTERN = /^w_[a-z0-9]{8,32}$/;

/** One person in a hand-written starting cast. */
export const PersonInput = z.object({
  name: z.string().trim().min(1, 'Every person needs a name').max(40),
  familyName: z.string().trim().max(40).optional(),
  sex: z.enum(['female', 'male']),
  age: z.number().min(0).max(95),
  occupation: z.string().trim().max(60).optional(),
  traits: z.string().trim().max(400).optional(),
  background: z.string().trim().max(1500).optional(),
  /** People with the same household number share a house. */
  household: z.number().int().min(0).max(40).optional(),
  /** First name of their partner in this cast. */
  partner: z.string().trim().max(40).optional(),
  /** First names of their parents in this cast. */
  parents: z.array(z.string().trim().max(40)).max(2).optional(),
  money: z.number().int().min(0).max(100000).optional(),
});
export type PersonInput = z.infer<typeof PersonInput>;

export const CastOption = z.discriminatedUnion('mode', [
  z.object({ mode: z.literal('sample') }),
  z.object({ mode: z.literal('custom'), people: z.array(PersonInput).min(1).max(80) }),
  z.object({
    mode: z.literal('generated'),
    adults: z.number().int().min(1).max(150),
    children: z.number().int().min(0).max(100),
    /** Flesh out the generated adults with an AI (needs a provider set up). */
    useAi: z.boolean().default(false),
  }),
]);
export type CastOption = z.input<typeof CastOption>;

export const CreateWorldRequest = z.object({
  name: z.string().trim().min(1, 'Name is required').max(60),
  seed: z.string().trim().max(64).optional(),
  mapSize: z.enum(['small', 'medium', 'large', 'huge']).default('medium'),
  cast: CastOption.default({ mode: 'sample' }),
  /** Brain for each starting villager, in cast order (see CastPreviewResponse). Missing = defaultBrain. */
  brains: z.array(BrainConfigSchema).max(250).optional(),
  /** Brain for newborns and spawned people (and any villager without one in `brains`). Default: mock. */
  defaultBrain: BrainConfigSchema.optional(),
});
export type CreateWorldRequest = z.input<typeof CreateWorldRequest>;

/** Who the starting villagers of a new world will be, so brains can be picked before it's created. */
export const CastPreviewRequest = z.object({
  /** Empty = the server picks a random seed and returns it; create the world with that seed. */
  seed: z.string().trim().max(64).optional(),
  cast: CastOption.default({ mode: 'sample' }),
});
export type CastPreviewRequest = z.input<typeof CastPreviewRequest>;

export interface CastPreviewPerson {
  /** Position in the cast; CreateWorldRequest.brains uses the same order. */
  index: number;
  name: string;
  familyName: string;
  sex: Sex;
  age: number;
  occupation: string;
}

export interface CastPreviewResponse {
  /** The seed the preview was made with (generated casts depend on it). */
  seed: string;
  people: CastPreviewPerson[];
}

/** AI usage, from the world's log of AI calls. */
export interface BrainUsage {
  calls: number;
  inputTokens: number;
  outputTokens: number;
  /** Cost of all the calls (USD), Claude-plan calls included at their API-price value. */
  costUsd: number;
  /** The part of `costUsd` covered by the owner's Claude subscription (not billed). */
  planUsd: number;
}

/** One person in the brains dialog: who they are, their brain and what it has used so far. */
export interface BrainRow extends BrainUsage {
  id: string;
  /** Full name. */
  name: string;
  age: number;
  stage: LifeStage;
  alive: boolean;
  brain: BrainConfig;
}

export interface BrainsResponse {
  defaultBrain: BrainConfig;
  /** Everyone who has lived in the world (the dead too, for their spending). */
  people: BrainRow[];
  /** Every AI call in the world, including ones not tied to a villager (e.g. drafting a spawn). */
  totals: BrainUsage;
}

/** Give several people the same brain at once. */
export const SetBrainsRequest = z.object({
  agentIds: z.array(z.string().max(40)).min(1).max(1000),
  brain: BrainConfigSchema,
});
export type SetBrainsRequest = z.infer<typeof SetBrainsRequest>;

export interface WorldsResponse {
  worlds: WorldMeta[];
  activeWorldId: string | null;
}

export interface WorldResponse {
  world: WorldMeta;
}

export interface RunnerStatus {
  running: boolean;
  /** Target ticks per second (0 = as fast as possible). */
  speed: number;
  /** Measured ticks per second over the last moment. */
  actualSpeed: number;
  /** Number of agents the world is currently waiting on to decide. */
  thinking: number;
  /** AI cost in this world (USD), Claude-plan calls at their API-price value; the cap counts it. */
  spentUsd: number;
  /** The part of `spentUsd` covered by the owner's Claude subscription (not billed). */
  planUsd: number;
  capUsd: number;
  /** Paused because the spending cap was reached. */
  capReached: boolean;
  /** Paused because a villager's AI provider hit a rate or usage limit. */
  rateLimit: RateLimitNotice | null;
}

/** What stopped the world when an AI provider said "too many requests" or "limit used up". */
export interface RateLimitNotice {
  /** The person whose decision hit the limit (it is asked again when time resumes). */
  agentId: string;
  agentName: string;
  provider: ProviderId;
  model: string;
  /** HTTP status, e.g. 429, when there was one. */
  status?: number;
  /** Which limit, in plain words (e.g. "requests per minute", "plan usage limit"). */
  limit?: string;
  /** The provider's retry-after, in seconds, if it sent one. */
  retryAfterSec?: number;
  /** The provider's own error message. */
  message: string;
  /** When it happened (ms since epoch). */
  at: number;
  /** When time resumes by itself (ms since epoch); null = waits for Play. */
  resumeAt: number | null;
}

export interface WorldViewResponse {
  meta: WorldMeta;
  settings: WorldSettings;
  map: WireMap;
  tick: number;
  runner: RunnerStatus;
  agents: AgentView[];
  /** Visible resource amounts by object id (berries on bushes, crops in fields). */
  resources: Record<string, number>;
  /** Owners' names by object id. */
  owners: Record<string, string[]>;
  conditions: ActiveCondition[];
  calendar: CalendarView;
}

/** The village beyond the town market: stalls, pens, owned fields, jobs, meetings and rules. */
export interface VillageResponse {
  leader: { id: string; name: string } | null;
  /** Coins in the village purse. */
  treasury: number;
  /** Daily levy each grown-up pays into the purse (0 = none). */
  taxPerDay: number;
  rules: { id: string; text: string; passedTick: number; proposerName: string }[];
  meetings: {
    id: string;
    topic: string;
    callerName: string;
    placeName: string;
    startTick: number;
    endTick: number;
    proposals: { id: string; text: string; byName: string; yes: number; no: number }[];
  }[];
  stalls: {
    id: string;
    name: string;
    owners: string[];
    stock: { item: string; quantity: number; price: number }[];
  }[];
  pens: { id: string; name: string; owners: string[]; hens: number; sheep: number; wool: number }[];
  /** Fields someone cleared (owned), with what grows there. */
  fields: { id: string; name: string; owners: string[]; crop: string | null; amount: number }[];
  jobs: {
    id: string;
    employerName: string;
    workerName: string;
    wage: number;
    startTick: number;
    endTick: number;
  }[];
}

export interface MarketResponse {
  stock: Record<string, number>;
  quotes: Record<string, { buy: number; sell: number }>;
  /** Total coins held by living villagers. */
  moneySupply: number;
}

export const ControlRequest = z.object({
  running: z.boolean().optional(),
  speed: z.number().int().min(0).max(2000).optional(),
});
export type ControlRequest = z.infer<typeof ControlRequest>;

export const WorldEventRequest = z.object({
  kind: z.enum(['drought', 'storm', 'disease', 'fire', 'bumper_harvest']),
  /** 0.2 (mild) – 1 (severe). */
  intensity: z.number().min(0.1).max(1).default(0.6),
  /** In-game hours (fire ignores this). */
  hours: z
    .number()
    .min(1)
    .max(24 * 30)
    .default(24),
  /** Optional target (a building for fire, a person to start a disease). */
  targetId: z.string().max(40).optional(),
});
export type WorldEventRequest = z.input<typeof WorldEventRequest>;

export interface ActiveCondition {
  id: string;
  kind: 'drought' | 'storm' | 'disease' | 'bumper_harvest' | 'fire';
  intensity: number;
  startTick: number;
  endTick: number;
  /** Fire: the burning building. */
  targetId?: string;
}

/** One entry in a person's life story. */
export interface StoryEntry {
  tick: number;
  text: string;
  kind: string;
  /** "event" = from the world's history (what happened); "memory" = in their own words. */
  source: 'event' | 'memory';
}

/** The world as it was at a past tick (replayed from the saved history; no AI calls). */
export interface ReplayResponse {
  tick: number;
  /** The range that can be replayed: from the first snapshot to the live tick. */
  firstTick: number;
  lastTick: number;
  agents: AgentView[];
  resources: Record<string, number>;
  conditions: ActiveCondition[];
  calendar: CalendarView;
  owners: Record<string, string[]>;
  mapVersion: number;
  /** Included when the map then differs from the version the viewer has. */
  map?: WireMap;
}

export const ReplayQuery = z.object({
  tick: z.coerce.number().int().min(0),
  /** The map version the viewer currently shows. */
  mapVersion: z.coerce.number().int().optional(),
});

export interface StoryResponse {
  entries: StoryEntry[];
}

export const ObjectHistoryQuery = z.object({
  /** The object as it was at this past tick (replay). Omitted = now. */
  tick: z.coerce.number().int().min(0).optional(),
});

/** Someone named in an object's history. */
export interface ObjectPerson {
  id: string;
  name: string;
}

/**
 * What the village's history knows about one map object (a house, bush, tree, field, the
 * market…): how it came to be and what has happened to it since. When replaying, everything is
 * as it was at that moment.
 */
export interface ObjectHistoryResponse {
  objectId: string;
  /** It was part of the village when the world was created (otherwise it was made later). */
  founded: boolean;
  /** When the world was created. */
  foundedTick: number;
  /**
   * Its history is complete from this tick on. Later than `foundedTick` for worlds made before
   * object history was kept: only building and fires were recovered from before then.
   */
  recordedSince: number;
  /** People who live there (alive). */
  residents: ObjectPerson[];
  /** Lasting changes (importance 3+), oldest first: built, burnt, rebuilt, inherited, births… */
  milestones: WorldEvent[];
  /** Day-to-day use (importance 1–2), newest first: the latest 20. */
  recent: WorldEvent[];
  /** Day-to-day uses in all. */
  uses: number;
  /** Who used it most: up to 5, most first. */
  regulars: (ObjectPerson & { count: number })[];
}

export const EventsQuery = z.object({
  limit: z.coerce.number().int().min(1).max(500).default(200),
  q: z.string().trim().max(100).optional(),
  atOrBeforeTick: z.coerce.number().int().min(0).optional(),
  beforeId: z.coerce.number().int().optional(),
  agentId: z.string().max(40).optional(),
  minImportance: z.coerce.number().int().min(1).max(5).default(1),
});
export type EventsQuery = z.input<typeof EventsQuery>;

export interface EventsResponse {
  events: WorldEvent[];
}

export interface AgentResponse {
  agent: AgentDetail;
}

export interface CallsResponse {
  calls: LlmCallView[];
}

/** A person and their relatives two generations up and down, for the family tree. */
export interface FamilyNode {
  id: string;
  name: string;
  sex: 'female' | 'male';
  age: number;
  alive: boolean;
  mother?: FamilyNode | null;
  father?: FamilyNode | null;
  partner?: { id: string; name: string; alive: boolean } | null;
  children?: FamilyNode[];
}

export interface AgentsResponse {
  agents: AgentView[];
}

export interface ApiError {
  error: string;
}

/** Messages the helper pushes to the browser over the WebSocket. */
export type ServerMessage =
  | { type: 'hello'; serverVersion: string; worlds: WorldMeta[]; activeWorldId: string | null }
  | { type: 'worlds_changed'; worlds: WorldMeta[]; activeWorldId: string | null }
  | {
      type: 'frame';
      worldId: string;
      tick: number;
      runner: RunnerStatus;
      agents: AgentView[];
      /** Only resources that changed since the previous frame. */
      resources: Record<string, number>;
      /** Changes when the map changes (e.g. a house is built), so viewers reload it. */
      mapVersion: number;
      conditions: ActiveCondition[];
      calendar: CalendarView;
    }
  | { type: 'events'; worldId: string; events: WorldEvent[] };

/** Messages the browser sends to the helper. Observer commands are added here in later phases. */
export const ClientMessage = z.discriminatedUnion('type', [z.object({ type: z.literal('ping') })]);
export type ClientMessage = z.infer<typeof ClientMessage>;
